    /**
     * Can access organization reports.
     */
    public let accessReports: Bool
    /**
     * Can create new collections.
     */
    public let createNewCollections: Bool
    /**
     * Can edit any collection, including those they are not assigned to.
     */
    public let editAnyCollection: Bool
    /**
     * Can delete any collection, including those they are not assigned to.
     */
    public let deleteAnyCollection: Bool
    /**
     * Can manage groups within the organization.
     */
    public let manageGroups: Bool
    /**
     * Can manage SSO configuration.
     */
    public let manageSso: Bool
    /**
     * Can manage organization policies.
     */
    public let managePolicies: Bool
    /**
     * Can manage organization members.
     */
    public let manageUsers: Bool
    /**
     * Can manage the account recovery (password reset) feature.
     */
    public let manageResetPassword: Bool
    /**
     * Can manage SCIM (System for Cross-domain Identity Management) configuration.
     */
    public let manageScim: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Can view the organization's event logs.
         */accessEventLogs: Bool, 
        /**
         * Can import and export organization vault data.
         */accessImportExport: Bool, 
        /**
         * Can access organization reports.
         */accessReports: Bool, 
        /**
         * Can create new collections.
         */createNewCollections: Bool, 
        /**
         * Can edit any collection, including those they are not assigned to.
         */editAnyCollection: Bool, 
        /**
         * Can delete any collection, including those they are not assigned to.
         */deleteAnyCollection: Bool, 
        /**
         * Can manage groups within the organization.
         */manageGroups: Bool, 
        /**
         * Can manage SSO configuration.
         */manageSso: Bool, 
        /**
         * Can manage organization policies.
         */managePolicies: Bool, 
        /**
         * Can manage organization members.
         */manageUsers: Bool, 
        /**
         * Can manage the account recovery (password reset) feature.
         */manageResetPassword: Bool, 
        /**
         * Can manage SCIM (System for Cross-domain Identity Management) configuration.
         */manageScim: Bool) {
        self.accessEventLogs = accessEventLogs
        self.accessImportExport = accessImportExport
        self.accessReports = accessReports
        self.createNewCollections = createNewCollections
        self.editAnyCollection = editAnyCollection
        self.deleteAnyCollection = deleteAnyCollection
        self.manageGroups = manageGroups
        self.manageSso = manageSso
        self.managePolicies = managePolicies
        self.manageUsers = manageUsers
        self.manageResetPassword = manageResetPassword
        self.manageScim = manageScim
    }

    

    
}

